task prime_num(n: int) returns (r: bool)
  ensures r == (n > 1 and forall k in [2, n - 1] . n % k != 0)
{
  if n <= 1 {
    r := false;
  } else {
    var i: int := 2;
    while i < n
      invariant i >= 2 and i <= n
      invariant r == (n > 1 and forall k in [2, i - 1] . n % k != 0)
      decreases n - i
    {
      if n % i == 0 {
        r := false;
      }
      i := i + 1;
    }
    r := true;
  }
}
